<div class="account-container"><section class="account-heading"><div><span class="eyebrow dark">MI CUENTA</span><h1>HOLA, <em><?=htmlspecialchars(strtoupper(customer_user()['name']))?>.</em></h1><p>Administra tus datos y revisa todas tus compras.</p></div><form method="post" action="<?=url('mi-cuenta/salir')?>"><input type="hidden" name="_token" value="<?=csrf()?>"><button class="account-logout">CERRAR SESIÓN</button></form></section><?php if(!empty($_SESSION['success'])):?><div class="account-flash"><?=htmlspecialchars($_SESSION['success']);unset($_SESSION['success']);?></div><?php endif;?><?php if(!empty($_SESSION['error'])):?><div class="demo-note"><?=htmlspecialchars($_SESSION['error']);unset($_SESSION['error']);?></div><?php endif;?><div class="account-grid"><section class="account-orders"><h2>MIS PEDIDOS</h2><?php if(!$orders):?><div class="account-empty">Aún no tienes pedidos asociados a esta cuenta.</div><?php endif;?><?php foreach($orders as $o):?><article><div><small>PEDIDO</small><b>#UMD-<?=str_pad((string)$o['id'],4,'0',STR_PAD_LEFT)?></b></div><div><small>FECHA</small><span><?=date('d/m/Y',strtotime($o['created_at']))?></span></div><div><small>PRODUCTOS</small><span><?=$o['items_count']?></span></div><div><small>TOTAL</small><strong><?=money((int)$o['total'])?></strong></div><em class="order-state <?=$o['status']?>"><?=strtoupper($o['status'])?></em><a href="<?=url('mi-cuenta/pedido?id='.$o['id'])?>">VER PEDIDO →</a></article><?php endforeach;?></section><aside class="account-security"><h2>SEGURIDAD</h2><p><?=htmlspecialchars(customer_user()['email'])?></p><form method="post" action="<?=url('mi-cuenta/clave')?>"><input type="hidden" name="_token" value="<?=csrf()?>"><label>CONTRASEÑA ACTUAL<input type="password" name="current_password" required></label><label>NUEVA CONTRASEÑA<input type="password" name="new_password" minlength="8" required></label><button>CAMBIAR CONTRASEÑA →</button></form></aside></div></div>
